files.app/api/health/route.ts:
import { NextResponse } from "next/server";

export const dynamic = "force-dynamic";

export function GET() {
  const environment = process.env.NEXT_PUBLIC_APP_ENV ?? "development";
  const commit = process.env.NEXT_PUBLIC_COMMIT_SHA ?? process.env.VERCEL_GIT_COMMIT_SHA ?? "unknown";
  const academicDataMode = process.env.NEXT_PUBLIC_ACADEMIC_DATA_MODE ?? "backend";
  const version = process.env.NEXT_PUBLIC_APP_VERSION ?? "staging-alpha";

  return NextResponse.json(
    {
      ok: true,
      app: "ENS English",
      environment,
      commit,
      academicDataMode,
      version,
      timestamp: new Date().toISOString(),
    },
    { headers: { "Cache-Control": "no-store" } },
  );
}

files.app/brand-polish.css:
.brand-mark {
  width: 50px;
  height: 60px;
  border-radius: 12px;
  background-color: #ffffff;
  background-image: url("https://ens-english-rebuild.vercel.app/assets/escudo-oficial.png");
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
  box-shadow: 0 4px 14px rgba(8, 46, 30, 0.14);
  overflow: hidden;
}

.brand-mark > svg {
  display: none;
}

.login-brand {
  align-items: center;
}

.login-card {
  border-top: 4px solid var(--yellow);
}

.login-card .eyebrow {
  letter-spacing: 0.06em;
}

.student-profile-page {
  display: grid;
  gap: 16px;
  max-width: 1120px;
}

.student-profile-hero {
  padding: clamp(24px, 4vw, 38px);
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) minmax(240px, 0.7fr);
  gap: 24px;
  align-items: center;
  overflow: hidden;
  position: relative;
}

.student-profile-hero::after {
  content: "";
  position: absolute;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  right: -90px;
  top: -110px;
  background: rgba(228, 184, 47, 0.13);
  pointer-events: none;
}

.student-profile-avatar {
  width: 104px;
  height: 104px;
  border-radius: 30px;
  display: grid;
  place-items: center;
  background: linear-gradient(145deg, var(--green), var(--green-dark));
  color: white;
  font-size: 34px;
  font-weight: 900;
  letter-spacing: -0.04em;
  box-shadow: 0 14px 28px rgba(15, 63, 43, 0.2);
}

.student-profile-heading h2 {
  margin: 7px 0 6px;
  font-size: clamp(30px, 4vw, 46px);
  line-height: 1;
  letter-spacing: -0.04em;
}

.student-profile-heading p {
  margin: 0;
  color: var(--muted);
  font-weight: 700;
}

.student-profile-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 15px;
}

.student-profile-badges span {
  padding: 7px 10px;
  border-radius: 999px;
  background: #edf6f1;
  color: var(--green-dark);
  font-size: 11px;
  font-weight: 900;
}

.student-profile-route {
  position: relative;
  z-index: 1;
  padding: 20px;
  border-radius: 18px;
  background: #f6faf8;
  border: 1px solid #dbe9e1;
}

.student-profile-route-head {
  display: flex;
  justify-content: space-between;
  gap: 15px;
  align-items: baseline;
}

.student-profile-route-head span,
.student-profile-route small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.student-profile-route-head strong {
  color: var(--green);
  font-size: 26px;
}

.student-profile-route-track {
  height: 10px;
  margin: 12px 0 9px;
  border-radius: 999px;
  background: #dfe9e3;
  overflow: hidden;
}

.student-profile-route-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--green), #2ca66b);
}

.student-profile-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.student-profile-metric {
  min-height: 104px;
  padding: 18px;
  display: flex;
  align-items: center;
  gap: 13px;
}

.profile-metric-icon {
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: #f4f7f5;
  font-size: 23px;
}

.student-profile-metric strong,
.student-profile-metric small {
  display: block;
}

.student-profile-metric strong {
  color: var(--green-dark);
  font-size: 25px;
  line-height: 1;
}

.student-profile-metric small {
  margin-top: 6px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
}

.student-profile-columns {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 0.8fr);
  gap: 16px;
}

.student-profile-card {
  padding: clamp(22px, 3vw, 30px);
}

.student-profile-card h3 {
  margin: 7px 0 18px;
  font-size: 22px;
}

.student-profile-info-grid {
  margin-top: 0;
}

.student-learning-summary {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.student-learning-summary > div {
  padding: 15px;
  border-radius: 14px;
  background: #f6f8f7;
}

.student-learning-summary strong,
.student-learning-summary span {
  display: block;
}

.student-learning-summary strong {
  color: var(--green);
  font-size: 27px;
}

.student-learning-summary span {
  margin-top: 4px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
}

.student-profile-action {
  width: 100%;
  margin-top: 14px;
}

.route-card {
  margin-top: 16px;
  padding: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 22px;
}

.route-card h3 {
  margin: 7px 0 6px;
  font-size: 24px;
}

.route-card p {
  margin: 0;
  color: var(--muted);
}

.secondary-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 13px;
}

.secondary-stats span {
  padding: 9px 12px;
  border-radius: 999px;
  background: white;
  border: 1px solid var(--line);
  color: var(--green-dark);
  font-size: 12px;
  font-weight: 800;
}

@media (max-width: 920px) {
  .student-profile-hero {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .student-profile-route {
    grid-column: 1 / -1;
  }

  .student-profile-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .student-profile-columns {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 560px) {
  .brand-mark {
    width: 44px;
    height: 53px;
  }

  .student-profile-hero {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .student-profile-avatar {
    width: 88px;
    height: 88px;
    margin: 0 auto;
    border-radius: 26px;
    font-size: 29px;
  }

  .student-profile-badges {
    justify-content: center;
  }

  .student-profile-metrics {
    grid-template-columns: 1fr 1fr;
  }

  .student-profile-metric {
    min-height: 96px;
    align-items: flex-start;
    flex-direction: column;
  }

  .student-learning-summary {
    grid-template-columns: 1fr 1fr;
  }

  .route-card {
    align-items: stretch;
    flex-direction: column;
  }
}

